-- PROPOSED Mira private catalog, schema version 1. Not installed by these docs.
-- UUIDs are generated by Go. Times are UTC Unix microseconds (INTEGER).
-- Enable foreign keys on EVERY catalog connection before any transaction.
-- Validate state transitions, final-owner rules, grant scope, policy payloads,
-- generation ownership, and manifest identity in common services as well.
-- Cross-file lifecycle effects are reconciled durable intents, not SQL atomicity.
PRAGMA foreign_keys = ON;

CREATE TABLE installation (
    id TEXT PRIMARY KEY, catalog_version INTEGER NOT NULL,
    native_revision TEXT NOT NULL, native_manifest_sha256 TEXT NOT NULL,
    state TEXT NOT NULL CHECK (state IN ('initializing','ready','draining','recovering')),
    revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0),
    created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE catalog_migrations (
    version INTEGER PRIMARY KEY, checksum TEXT NOT NULL,
    applied_at INTEGER NOT NULL, executable_version TEXT NOT NULL
);
CREATE TABLE settings (
    key TEXT PRIMARY KEY, value_json TEXT NOT NULL, source TEXT NOT NULL,
    revision INTEGER NOT NULL CHECK (revision > 0), updated_at INTEGER NOT NULL
);
CREATE TABLE secret_references (
    id TEXT PRIMARY KEY, kind TEXT NOT NULL, locator TEXT NOT NULL,
    fingerprint TEXT, state TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1,
    created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
); -- locator is an OS-protected reference, never a raw key/password.
CREATE TABLE principals (
    id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('user','service','agent')),
    name TEXT NOT NULL, enabled INTEGER NOT NULL CHECK (enabled IN (0,1)),
    deleted_at INTEGER, policy_epoch INTEGER NOT NULL DEFAULT 1,
    revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE local_passwords (
    principal_id TEXT PRIMARY KEY REFERENCES principals(id),
    login_name TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL,
    hash_parameters_json TEXT NOT NULL, scram_verifier_ref TEXT REFERENCES secret_references(id),
    changed_at INTEGER NOT NULL
); -- No password reversibility. SCRAM verifier protection has its own threat model.
CREATE TABLE organizations (
    id TEXT PRIMARY KEY, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE,
    state TEXT NOT NULL, defaults_json TEXT NOT NULL DEFAULT '{}',
    revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE groups (
    id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id),
    name TEXT NOT NULL, slug TEXT NOT NULL, defaults_json TEXT NOT NULL DEFAULT '{}',
    revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
    UNIQUE (organization_id, slug), UNIQUE (id, organization_id)
);
CREATE TABLE roles (
    id TEXT PRIMARY KEY, organization_id TEXT REFERENCES organizations(id),
    name TEXT NOT NULL, builtin INTEGER NOT NULL DEFAULT 0 CHECK (builtin IN (0,1)),
    permissions_json TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1,
    created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE memberships (
    organization_id TEXT NOT NULL REFERENCES organizations(id),
    principal_id TEXT NOT NULL REFERENCES principals(id), role_id TEXT NOT NULL REFERENCES roles(id),
    revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
    PRIMARY KEY (organization_id, principal_id)
);
CREATE TABLE invitations (
    id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id),
    role_id TEXT NOT NULL REFERENCES roles(id), code_hash TEXT NOT NULL UNIQUE,
    created_by TEXT NOT NULL REFERENCES principals(id), redeemed_by TEXT REFERENCES principals(id),
    expires_at INTEGER NOT NULL, redeemed_at INTEGER, revoked_at INTEGER,
    revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL
);
CREATE TABLE credentials (
    id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id), name TEXT NOT NULL,
    kind TEXT NOT NULL, fingerprint TEXT NOT NULL UNIQUE, secret_hash TEXT NOT NULL,
    scopes_json TEXT NOT NULL, expires_at INTEGER NOT NULL, revoked_at INTEGER,
    last_used_at INTEGER, replaced_by TEXT REFERENCES credentials(id),
    revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL
);
CREATE TABLE login_sessions (
    id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id),
    credential_id TEXT REFERENCES credentials(id), token_hash TEXT NOT NULL UNIQUE,
    expires_at INTEGER NOT NULL, revoked_at INTEGER, policy_epoch INTEGER NOT NULL,
    created_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL
);
CREATE TABLE credential_verifiers (
    credential_id TEXT NOT NULL REFERENCES credentials(id), method TEXT NOT NULL,
    verifier_ref TEXT NOT NULL REFERENCES secret_references(id),
    parameters_json TEXT NOT NULL, changed_at INTEGER NOT NULL,
    PRIMARY KEY (credential_id, method)
); -- SCRAM verifiers are distinct from opaque-token/password hashes.
-- Secret-delivery envelopes reside under the protected secrets store, bound to
-- credential/invitation identity and idempotency scope; only hashes/references
-- enter catalog receipts. They expire independently and are excluded from
-- ordinary catalog export and job results. See security.md for the retry rule.
CREATE TABLE identity_providers (
    id TEXT PRIMARY KEY, issuer TEXT NOT NULL UNIQUE, audience_json TEXT NOT NULL,
    jwks_url TEXT NOT NULL, mapping_json TEXT NOT NULL, enabled INTEGER NOT NULL,
    revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE grants (
    id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id),
    resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, actions_json TEXT NOT NULL,
    selector_json TEXT NOT NULL DEFAULT '{}', granted_by TEXT NOT NULL REFERENCES principals(id),
    revoked_at INTEGER, revision INTEGER NOT NULL DEFAULT 1,
    created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
); -- Polymorphic resources require a typed service-level existence/scope check.
CREATE INDEX grants_subject_resource ON grants(principal_id, resource_type, resource_id);
CREATE TABLE policy_epochs (
    resource_type TEXT NOT NULL, resource_id TEXT NOT NULL,
    epoch INTEGER NOT NULL CHECK (epoch > 0), updated_at INTEGER NOT NULL,
    PRIMARY KEY (resource_type, resource_id)
);

CREATE TABLE databases (
    id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id),
    group_id TEXT, name TEXT NOT NULL, slug TEXT NOT NULL,
    provider TEXT NOT NULL CHECK (provider IN ('turso')),
    dialect TEXT NOT NULL CHECK (dialect IN ('sqlite','postgres')),
    persistence TEXT NOT NULL CHECK (persistence IN ('persistent','memory')),
    state TEXT NOT NULL CHECK (state IN ('creating','ready','draining','restoring','migrating','deleting','trashed','purging','purged','failed')),
    active_generation_id TEXT REFERENCES generations(id) DEFERRABLE INITIALLY DEFERRED,
    schema_revision INTEGER NOT NULL DEFAULT 0,
    read_blocked INTEGER NOT NULL DEFAULT 0 CHECK (read_blocked IN (0,1)),
    write_blocked INTEGER NOT NULL DEFAULT 0 CHECK (write_blocked IN (0,1)),
    deletion_protected INTEGER NOT NULL DEFAULT 0 CHECK (deletion_protected IN (0,1)),
    limits_json TEXT NOT NULL DEFAULT '{}', features_json TEXT NOT NULL DEFAULT '{}',
    history_policy_json TEXT NOT NULL DEFAULT '{}', sync_policy_json TEXT NOT NULL DEFAULT '{}',
    cdc_policy_json TEXT NOT NULL DEFAULT '{}',
    revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
    UNIQUE (organization_id, slug), FOREIGN KEY (group_id, organization_id) REFERENCES groups(id, organization_id)
);
CREATE INDEX databases_group_page ON databases(group_id, created_at, id);
CREATE INDEX databases_org_page ON databases(organization_id, created_at, id);
CREATE TABLE generations (
    id TEXT PRIMARY KEY, database_id TEXT NOT NULL REFERENCES databases(id),
    parent_generation_id TEXT REFERENCES generations(id), native_revision TEXT NOT NULL,
    storage_format TEXT NOT NULL, journal_mode TEXT NOT NULL,
    manifest_sha256 TEXT, relative_path TEXT NOT NULL UNIQUE,
    encryption_key_ref TEXT REFERENCES secret_references(id),
    state TEXT NOT NULL CHECK (state IN ('staging','verified','active','retained','deleting','deleted','failed')),
    first_commit TEXT, last_commit TEXT, created_at INTEGER NOT NULL, published_at INTEGER,
    UNIQUE (id, database_id)
);
-- Application checks that databases.active_generation_id belongs to that database.
-- Only ready+active compatible identities admit sessions; paths never come from public labels.
CREATE TABLE templates (
    id TEXT PRIMARY KEY, organization_id TEXT REFERENCES organizations(id), name TEXT NOT NULL,
    dialect TEXT NOT NULL CHECK (dialect IN ('sqlite','postgres')), sql_text TEXT NOT NULL,
    checksum TEXT NOT NULL, capabilities_json TEXT NOT NULL,
    revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE migration_runs (
    id TEXT PRIMARY KEY, database_id TEXT NOT NULL REFERENCES databases(id),
    generation_id TEXT NOT NULL REFERENCES generations(id), migration_key TEXT NOT NULL,
    checksum TEXT NOT NULL, schema_revision_before INTEGER NOT NULL,
    schema_revision_after INTEGER, state TEXT NOT NULL,
    target_receipt_id TEXT, error_json TEXT, created_at INTEGER NOT NULL, completed_at INTEGER,
    UNIQUE (generation_id, migration_key)
); -- A corresponding receipt in the TARGET database transaction is required.
CREATE TABLE enabled_extensions (
    database_id TEXT NOT NULL REFERENCES databases(id), extension_id TEXT NOT NULL,
    version TEXT NOT NULL, artifact_digest TEXT NOT NULL, configuration_json TEXT NOT NULL,
    state TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1,
    PRIMARY KEY (database_id, extension_id)
);

CREATE TABLE jobs (
    id TEXT PRIMARY KEY, operation_id TEXT NOT NULL, principal_id TEXT NOT NULL REFERENCES principals(id),
    credential_id TEXT REFERENCES credentials(id), resource_type TEXT, resource_id TEXT,
    generation_id TEXT REFERENCES generations(id),
    state TEXT NOT NULL CHECK (state IN ('queued','running','waiting','cancelling','cancelled','succeeded','failed','unknown_commit_state')),
    payload_json TEXT NOT NULL, payload_digest TEXT NOT NULL,
    lease_owner TEXT, lease_epoch INTEGER NOT NULL DEFAULT 0, lease_until INTEGER,
    attempt INTEGER NOT NULL DEFAULT 0, next_attempt_at INTEGER,
    progress_unit TEXT, progress_current INTEGER, progress_total INTEGER,
    commit_state TEXT NOT NULL DEFAULT 'not_started' CHECK (commit_state IN ('not_started','in_transaction','rolled_back','committed','unknown_commit_state')),
    cancel_requested_at INTEGER, result_json TEXT, error_json TEXT,
    revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE INDEX jobs_runnable ON jobs(state, next_attempt_at, created_at, id);
CREATE INDEX jobs_resource_page ON jobs(resource_type, resource_id, created_at, id);
CREATE TABLE job_events (
    job_id TEXT NOT NULL REFERENCES jobs(id), sequence INTEGER NOT NULL,
    kind TEXT NOT NULL, event_json TEXT NOT NULL, created_at INTEGER NOT NULL,
    PRIMARY KEY (job_id, sequence)
);
CREATE TABLE lifecycle_intents (
    id TEXT PRIMARY KEY, job_id TEXT NOT NULL UNIQUE REFERENCES jobs(id),
    database_id TEXT REFERENCES databases(id), expected_generation_id TEXT REFERENCES generations(id),
    desired_generation_id TEXT REFERENCES generations(id), expected_revision INTEGER,
    phase TEXT NOT NULL, staging_manifest_sha256 TEXT, published_manifest_sha256 TEXT,
    reconcile_json TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1,
    created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE idempotency_records (
    principal_id TEXT NOT NULL REFERENCES principals(id), operation_id TEXT NOT NULL,
    resource_scope TEXT NOT NULL, key_hash TEXT NOT NULL, payload_digest TEXT NOT NULL,
    state TEXT NOT NULL, job_id TEXT REFERENCES jobs(id), result_json TEXT,
    expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL,
    PRIMARY KEY (principal_id, operation_id, resource_scope, key_hash)
); -- Does not establish arbitrary user-SQL exactly-once writes by itself.
CREATE TABLE file_assets (
    id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id),
    intended_operation TEXT NOT NULL, media_type TEXT NOT NULL,
    relative_path TEXT NOT NULL UNIQUE, state TEXT NOT NULL,
    size_limit INTEGER NOT NULL, size_bytes INTEGER NOT NULL DEFAULT 0,
    sha256 TEXT, expires_at INTEGER NOT NULL,
    revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE upload_chunks (
    asset_id TEXT NOT NULL REFERENCES file_assets(id), chunk_index INTEGER NOT NULL CHECK (chunk_index >= 0),
    size_bytes INTEGER NOT NULL CHECK (size_bytes >= 0), sha256 TEXT NOT NULL,
    PRIMARY KEY (asset_id, chunk_index)
);
CREATE TABLE snapshots (
    id TEXT PRIMARY KEY, database_id TEXT NOT NULL REFERENCES databases(id),
    generation_id TEXT NOT NULL REFERENCES generations(id), job_id TEXT REFERENCES jobs(id),
    name TEXT, state TEXT NOT NULL, manifest_sha256 TEXT, commit_revision TEXT,
    boundary_json TEXT NOT NULL, size_bytes INTEGER, verification_json TEXT,
    revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, completed_at INTEGER
);
CREATE INDEX snapshots_database_page ON snapshots(database_id, created_at, id);
CREATE TABLE history_segments (
    id TEXT PRIMARY KEY, database_id TEXT NOT NULL REFERENCES databases(id),
    generation_id TEXT NOT NULL REFERENCES generations(id), archive_generation TEXT NOT NULL,
    sequence INTEGER NOT NULL, first_revision TEXT NOT NULL, last_revision TEXT NOT NULL,
    first_committed_at INTEGER NOT NULL, last_committed_at INTEGER NOT NULL,
    previous_digest TEXT, manifest_sha256 TEXT NOT NULL, format_version INTEGER NOT NULL,
    state TEXT NOT NULL, created_at INTEGER NOT NULL,
    UNIQUE (generation_id, archive_generation, sequence)
);
CREATE INDEX history_time_range ON history_segments(generation_id, first_committed_at, last_committed_at);
CREATE TABLE branches (
    id TEXT PRIMARY KEY, database_id TEXT NOT NULL UNIQUE REFERENCES databases(id),
    source_database_id TEXT NOT NULL REFERENCES databases(id),
    source_generation_id TEXT NOT NULL REFERENCES generations(id),
    source_revision TEXT NOT NULL, base_manifest_sha256 TEXT NOT NULL,
    snapshot_id TEXT NOT NULL REFERENCES snapshots(id), created_at INTEGER NOT NULL
);
CREATE TABLE object_manifests (
    digest TEXT PRIMARY KEY, format_version INTEGER NOT NULL, kind TEXT NOT NULL,
    size_bytes INTEGER NOT NULL, state TEXT NOT NULL, created_at INTEGER NOT NULL, verified_at INTEGER
);
CREATE TABLE manifest_edges (
    parent_digest TEXT NOT NULL REFERENCES object_manifests(digest),
    child_digest TEXT NOT NULL REFERENCES object_manifests(digest),
    PRIMARY KEY (parent_digest, child_digest)
);
CREATE TABLE retention_roots (
    resource_type TEXT NOT NULL, resource_id TEXT NOT NULL,
    manifest_digest TEXT NOT NULL REFERENCES object_manifests(digest),
    expires_at INTEGER, created_at INTEGER NOT NULL,
    PRIMARY KEY (resource_type, resource_id, manifest_digest)
);
CREATE TABLE backup_destinations (
    id TEXT PRIMARY KEY, name TEXT NOT NULL, canonical_path TEXT NOT NULL UNIQUE,
    identity_json TEXT NOT NULL, enabled INTEGER NOT NULL,
    revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE backup_policies (
    id TEXT PRIMARY KEY, name TEXT NOT NULL,
    destination_id TEXT NOT NULL REFERENCES backup_destinations(id),
    schedule TEXT NOT NULL, timezone TEXT NOT NULL, retention_json TEXT NOT NULL,
    verify INTEGER NOT NULL CHECK (verify IN (0,1)), enabled INTEGER NOT NULL CHECK (enabled IN (0,1)),
    next_run_at INTEGER, revision INTEGER NOT NULL DEFAULT 1,
    created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
);
CREATE TABLE backup_policy_databases (
    policy_id TEXT NOT NULL REFERENCES backup_policies(id), database_id TEXT NOT NULL REFERENCES databases(id),
    PRIMARY KEY (policy_id, database_id)
);
CREATE TABLE backup_artifacts (
    id TEXT PRIMARY KEY, destination_id TEXT NOT NULL REFERENCES backup_destinations(id),
    policy_id TEXT REFERENCES backup_policies(id), job_id TEXT NOT NULL REFERENCES jobs(id),
    state TEXT NOT NULL, manifest_sha256 TEXT, size_bytes INTEGER,
    verification_json TEXT, revision INTEGER NOT NULL DEFAULT 1,
    created_at INTEGER NOT NULL, completed_at INTEGER, expires_at INTEGER
);
CREATE TABLE backup_databases (
    backup_id TEXT NOT NULL REFERENCES backup_artifacts(id), database_id TEXT NOT NULL REFERENCES databases(id),
    generation_id TEXT NOT NULL REFERENCES generations(id), snapshot_id TEXT NOT NULL REFERENCES snapshots(id),
    commit_revision TEXT NOT NULL, PRIMARY KEY (backup_id, database_id)
);
CREATE TABLE recovery_plans (
    id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id),
    inputs_json TEXT NOT NULL, resolved_json TEXT NOT NULL, dependencies_digest TEXT NOT NULL,
    expires_at INTEGER NOT NULL, revision INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL
);
CREATE TABLE trash (
    id TEXT PRIMARY KEY, database_id TEXT NOT NULL REFERENCES databases(id),
    generation_id TEXT NOT NULL REFERENCES generations(id), job_id TEXT NOT NULL REFERENCES jobs(id),
    manifest_sha256 TEXT NOT NULL, ownership_json TEXT NOT NULL,
    deleted_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, restored_at INTEGER,
    revision INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE sync_clients (
    id TEXT PRIMARY KEY, database_id TEXT NOT NULL REFERENCES databases(id),
    generation_id TEXT NOT NULL REFERENCES generations(id), principal_id TEXT NOT NULL REFERENCES principals(id),
    credential_id TEXT REFERENCES credentials(id), protocol_version TEXT NOT NULL,
    capabilities_json TEXT NOT NULL, acknowledged_revision TEXT,
    revoked_at INTEGER, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL
);
CREATE INDEX sync_clients_retention ON sync_clients(generation_id, expires_at, revoked_at);
CREATE TABLE sync_checkpoints (
    client_id TEXT NOT NULL REFERENCES sync_clients(id), batch_id TEXT NOT NULL,
    payload_digest TEXT NOT NULL, target_receipt_id TEXT, result_json TEXT,
    state TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (client_id, batch_id)
);
CREATE TABLE subscription_cursors (
    id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id),
    credential_id TEXT REFERENCES credentials(id), database_id TEXT NOT NULL REFERENCES databases(id),
    generation_id TEXT NOT NULL REFERENCES generations(id), kind TEXT NOT NULL,
    selection_json TEXT NOT NULL, cursor TEXT, policy_epoch INTEGER NOT NULL,
    schema_revision INTEGER NOT NULL, state TEXT NOT NULL, expires_at INTEGER NOT NULL,
    created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL
); -- Native session/portal handles are ephemeral and deliberately absent.
CREATE TABLE audit_events (
    id TEXT PRIMARY KEY, request_id TEXT NOT NULL, job_id TEXT REFERENCES jobs(id),
    principal_id TEXT REFERENCES principals(id), credential_id TEXT REFERENCES credentials(id),
    interface TEXT NOT NULL, operation_id TEXT NOT NULL, resource_type TEXT, resource_id TEXT,
    generation_id TEXT, outcome TEXT NOT NULL, commit_state TEXT,
    payload_digest TEXT, redacted_details_json TEXT NOT NULL, created_at INTEGER NOT NULL
); -- Append-only under the service boundary; privileged OS owners can alter files.
CREATE INDEX audit_resource_page ON audit_events(resource_type, resource_id, created_at, id);
CREATE INDEX audit_principal_page ON audit_events(principal_id, created_at, id);
